"""Human-readable Guard operations dashboard shell."""

GUARD_OPERATIONS_PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Guard operations</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;color:#17202a;background:#eef2f6;line-height:1.4}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1480px;margin:auto;padding:28px 22px 56px}header{margin-bottom:20px}h1,h2,h3,h4,p{margin:0}h1{font-size:1.7rem;letter-spacing:-.02em}.muted{color:#687785;font-size:.86rem}.filters,.summary,.chat-card,.panel{background:#fff;border:1px solid #d9e1e8;border-radius:14px;box-shadow:0 2px 8px #1b34400b}.filters{display:flex;gap:9px;flex-wrap:wrap;align-items:center;padding:12px;margin-bottom:16px}.filters input,.filters select,.filters button,.filters label{font:inherit}.filters input,.filters select,.filters button{padding:8px 10px;border:1px solid #c7d1da;border-radius:8px;background:#fff}.filters button{cursor:pointer}.filters .primary{background:#1768cf;color:#fff;border-color:#1768cf}.filters .refresh{margin-left:auto}.filters label{display:flex;align-items:center;gap:5px;color:#42515e;font-size:.9rem}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:9px;padding:10px;margin-bottom:20px}.metric{padding:10px 12px;border-left:3px solid #1768cf;background:#f7f9fb;border-radius:7px}.metric strong{display:block;font-size:1.35rem;letter-spacing:-.02em}.metric span{font-size:.76rem;color:#687785}.chat-card{padding:18px;margin-bottom:18px}.chat-header{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.chat-title{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.chat-title h2{font-size:1.2rem;letter-spacing:-.015em}.subline{margin-top:4px}.badges{display:flex;gap:5px;align-items:center;flex-wrap:wrap}.badge{display:inline-flex;align-items:center;border-radius:999px;padding:4px 9px;font-size:.74rem;font-weight:700;text-transform:uppercase;letter-spacing:.035em;background:#e7edf2;color:#485865}.badge.private{background:#e3f5eb;color:#176b43}.badge.group{background:#eee8ff;color:#5a32a3}.badge.none{background:#e9eef2;color:#52616c}.badge.watch{background:#fff3cc;color:#795a00}.badge.concerning{background:#ffe6cd;color:#9a4d00}.badge.urgent{background:#ffe0e3;color:#a0263b}.badge.ok{background:#e3f5eb;color:#176b43}.badge.fail{background:#ffe0e3;color:#a0263b}.technical{margin-top:10px}.technical summary{cursor:pointer;color:#687785;font-size:.78rem}.technical-content{display:flex;gap:15px;flex-wrap:wrap;margin-top:6px;font-family:ui-monospace,SFMono-Regular,monospace;font-size:.72rem;color:#687785}.state-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(260px,.75fr);gap:12px;margin-top:17px}.panel{padding:15px;box-shadow:none}.panel h3{font-size:.76rem;text-transform:uppercase;letter-spacing:.07em;color:#687785;margin-bottom:9px}.current-decision{display:flex;align-items:center;gap:12px;margin-bottom:10px}.current-decision .badge{font-size:.86rem;padding:6px 12px}.current-decision strong{font-size:1.05rem}.explanation{font-size:1rem;max-width:850px}.meta-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:13px}.meta-item{padding:8px 10px;background:#f7f9fb;border-radius:8px}.meta-item strong{display:block;font-size:.96rem}.meta-item span{font-size:.73rem;color:#687785}.chips{display:flex;gap:4px;flex-wrap:wrap}.chip{display:inline-block;border-radius:999px;padding:3px 8px;background:#e7edf2;color:#435461;font-size:.76rem}.policy-status{display:flex;gap:8px;align-items:flex-start}.policy-status strong{font-size:1rem}.policy-detail{margin-top:7px;font-size:.86rem}.row{margin-top:10px}.queue-strip{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:13px;padding:10px 12px;background:#f7f9fb;border-radius:9px;font-size:.84rem}.queue-strip strong{font-weight:700}.queue-strip .sep{color:#aab4bc}.section{margin-top:17px;border-top:1px solid #e2e8ed;padding-top:15px}.section>summary{cursor:pointer;list-style:none;display:flex;align-items:center;gap:9px}.section>summary::-webkit-details-marker{display:none}.section>summary:before{content:'▸';color:#1768cf}.section[open]>summary:before{content:'▾'}.section-title{font-size:1rem;font-weight:750}.section-count{font-size:.78rem;color:#687785}.transitions{display:grid;gap:8px;margin-top:12px}.transition{border:1px solid #dce4ea;border-radius:10px;background:#fbfcfd}.transition>summary{cursor:pointer;list-style:none;padding:12px 13px;display:grid;grid-template-columns:auto minmax(80px,1fr) auto auto;gap:10px;align-items:center}.transition>summary::-webkit-details-marker{display:none}.transition>summary:before{content:'▸';color:#1768cf}.transition[open]>summary:before{content:'▾'}.transition-range{font-size:.84rem;font-weight:700}.transition-period{font-size:.78rem;color:#687785}.transition-count{font-size:.76rem;color:#687785;text-align:right}.transition-body{padding:0 13px 13px;border-top:1px solid #e5eaee}.transition-summary{display:flex;gap:10px;flex-wrap:wrap;padding:10px 0 7px;font-size:.83rem}.transition-reason{font-size:.85rem;color:#42515e;margin-bottom:10px}.compact-list{display:grid;gap:5px}.compact-analysis{display:block;padding:0;background:#f7f9fb;border-radius:7px;font-size:.8rem}.compact-analysis>summary{cursor:pointer;list-style:none;display:grid;grid-template-columns:90px 145px auto 1fr;gap:9px;align-items:baseline;padding:8px 9px}.compact-analysis>summary::-webkit-details-marker{display:none}.compact-analysis>summary:before{content:'▸';color:#1768cf}.compact-analysis[open]>summary:before{content:'▾'}.compact-analysis strong{font-size:.76rem}.compact-analysis .reason{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#52616c}.compact-detail{padding:0 10px 10px;border-top:1px solid #e1e7eb}.compact-detail h4{margin:8px 0 4px;font-size:.72rem;text-transform:uppercase;letter-spacing:.05em;color:#687785}.all-history{margin-top:12px}.analysis-log{display:grid;gap:7px;margin-top:12px}.analysis-row{border:1px solid #e0e7ec;border-radius:9px;background:#fff}.analysis-row>summary{cursor:pointer;list-style:none;padding:10px 12px;display:grid;grid-template-columns:90px 155px auto 1fr auto;gap:9px;align-items:baseline;font-size:.82rem}.analysis-row>summary::-webkit-details-marker{display:none}.analysis-row>summary:before{content:'▸';color:#1768cf}.analysis-row[open]>summary:before{content:'▾'}.analysis-row .reason{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#52616c}.analysis-detail{padding:0 12px 13px;border-top:1px solid #e5eaee}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:11px}.box{background:#f7f9fb;border-radius:8px;padding:10px}.box h4{font-size:.72rem;text-transform:uppercase;letter-spacing:.06em;color:#687785;margin-bottom:6px}.evidence{margin-top:6px;padding:8px;background:#fff;border-left:3px solid #1768cf;white-space:pre-wrap;font-size:.82rem}.timeline{border-left:2px solid #dfe5ea;margin:12px 0 0 5px;padding-left:14px}.event{position:relative;margin:0 0 10px}.event:before{content:"";position:absolute;left:-21px;top:7px;width:8px;height:8px;border-radius:50%;background:#1768cf}.event-title{font-weight:700;font-size:.86rem}.event-meta{font-size:.74rem;color:#687785}.event-detail{font-size:.8rem;margin-top:2px;white-space:pre-wrap}.empty{padding:36px;text-align:center}.warning{color:#9a4d00;background:#fff4dc;border:1px solid #f0d39a;border-radius:8px;padding:9px 11px;font-size:.82rem;margin-top:10px}@media(max-width:900px){.state-grid{grid-template-columns:1fr}.compact-analysis>summary{grid-template-columns:80px 125px 1fr}.compact-analysis>summary .reason{grid-column:1/-1}.analysis-row>summary{grid-template-columns:75px 125px auto 1fr}.analysis-row .reason{grid-column:1/-1}}@media(max-width:600px){.wrap{padding:16px 10px 40px}.chat-card{padding:13px}.meta-grid{grid-template-columns:1fr 1fr}.transition>summary{grid-template-columns:auto 1fr auto}.transition-period{grid-column:2}.transition-count{grid-column:3;grid-row:1/3}.two-col{grid-template-columns:1fr}.analysis-row>summary{grid-template-columns:70px 1fr auto}.analysis-row .reason{grid-column:1/-1}}
</style></head><body><main class="wrap"><header><h1>Guard operations</h1><div id="status" class="muted">Loading monitored chats…</div></header>
<form class="filters" onsubmit="load(event)"><select id="mode"><option value="">All chat types</option><option value="private">Private</option><option value="group">Groups</option></select><select id="decision"><option value="">Current decision</option><option>none</option><option>watch</option><option>concerning</option><option>urgent</option></select><input id="category" placeholder="Current category"><input id="chat" placeholder="Chat ID"><label><input id="overdue" type="checkbox"> overdue only</label><input id="from" type="date"><input id="to" type="date"><button class="primary">Apply filters</button><button type="button" class="refresh" onclick="load()">Refresh</button></form><section id="summary" class="summary"></section><section id="results"></section></main>
<script>
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const fmt=v=>v?new Date(v).toLocaleString(): '—';
const shortFmt=v=>v?new Date(v).toLocaleDateString(): '—';
const decisionClass=v=>['none','watch','concerning','urgent'].includes(v)?v:'';
const chips=v=>v&&v.length?v.map(x=>`<span class="chip">${esc(x)}</span>`).join(''):'<span class="muted">none</span>';
async function load(e){if(e)e.preventDefault();const p=new URLSearchParams();for(const [id,key] of [['mode','mode'],['decision','decision'],['category','category'],['chat','chat_id'],['from','date_from'],['to','date_to']]){const v=document.getElementById(id).value;if(v)p.set(key,v)}if(document.getElementById('overdue').checked)p.set('overdue','true');const r=await fetch('/api/debug/guard/operations?'+p);if(r.status===401){location.href='/q/expired';return}if(!r.ok){document.getElementById('status').textContent='Could not load operations ('+r.status+')';return}render(await r.json())}
function render(data){const s=data.summary;document.getElementById('status').textContent=`Updated ${fmt(data.generated_at)} · ${s.monitored_chats} monitored chats`;document.getElementById('summary').innerHTML=[['monitored_chats','Monitored chats'],['analyzed_chats','With analysis'],['pending_chats','Pending'],['overdue_chats','Overdue'],['alerts','Alerts'],['delivery_failures','Delivery failures']].map(([k,l])=>`<div class="metric"><strong>${esc(s[k])}</strong><span>${l}</span></div>`).join('');document.getElementById('results').innerHTML=data.chats.map(renderChat).join('')||'<div class="chat-card empty">No Guard chats match these filters.</div>'}
function renderChat(x){const d=x.latest_analysis||{};const current=d.decision||x.last_decision||'none';const p=x.latest_policy;const dl=x.latest_delivery;const mode=x.is_group?'group':'private';const policy=p?`<span class="badge ${p.reason==='not_actionable'?'ok':p.reason==='policy_suppressed'?'concerning':''}">${esc(p.reason)}</span><div class="policy-detail">${esc(p.detail)}</div>`:'<span class="badge">not evaluated</span><div class="policy-detail">No policy evaluation is recorded for the latest analysis.</div>';const historyNote=x.analysis_history_complete?`${x.analysis_count} analyses`:`${x.analysis_count}+ analyses loaded`;return `<article class="chat-card"><div class="chat-header"><div><div class="chat-title"><h2>${esc(x.chat_name||x.chat_id)}</h2><span class="badge ${mode}">${mode}</span><span class="badge ${decisionClass(current)}">${esc(current)}</span></div><div class="subline muted">Last message ${fmt(x.last_message_at)} · last analyzed ${fmt(x.last_analysis_at)} · ${historyNote}</div></div><div class="badges">${x.overdue?'<span class="badge fail">overdue</span>':''}${dl&&dl.action_status==='succeeded'?'<span class="badge ok">delivered</span>':''}</div></div><details class="technical"><summary>Technical details</summary><div class="technical-content"><span>chat ${esc(x.chat_id)}</span><span>child ${esc(x.child_user_id)}</span><span>activity v${esc(x.activity_version)}</span><span>analyzed v${esc(x.last_analyzed_version)}</span></div></details><div class="state-grid"><section class="panel"><h3>Current state</h3><div class="current-decision"><span class="badge ${decisionClass(current)}">${esc(current)}</span><strong>Latest analyzer decision</strong></div><p class="explanation">${esc(d.reason||'No analysis has committed yet.')}</p><div class="meta-grid"><div class="meta-item"><strong>${esc(d.confidence??'—')}</strong><span>confidence</span></div><div class="meta-item"><strong>${esc((d.evidence_message_ids||[]).length)}</strong><span>evidence messages</span></div><div class="meta-item"><strong>${esc(x.backlog)}</strong><span>queue backlog</span></div></div><div class="row"><b>Signals</b><div class="chips">${chips(d.signals)}</div></div><div class="row"><b>Categories</b><div class="chips">${chips(d.categories)}</div></div></section><section class="panel"><h3>Alert outcome</h3><div class="policy-status">${policy}</div><div class="row"><b>Delivery</b><div class="policy-detail">${dl?`${esc(dl.action_status||dl.alert_status)} · ${esc(dl.reason)}${dl.error?' · '+esc(dl.error):''}`:'No alert created for the latest analysis.'}</div></div><div class="row"><b>Threshold episodes</b><div class="chips">${x.threshold_states.length?x.threshold_states.map(t=>`<span class="chip">${esc(t.threshold_family)} · ${esc(t.status)}${t.current_kind?' · '+esc(t.current_kind):''}</span>`).join(''):'<span class="muted">none recorded</span>'}</div></div></section></div><div class="queue-strip"><strong>Queue</strong><span>activity v${esc(x.activity_version)}</span><span class="sep">·</span><span>analyzed v${esc(x.last_analyzed_version)}</span><span class="sep">·</span><span>${esc(x.backlog)} backlog</span><span class="sep">·</span><span>${x.overdue?'<span class="badge fail">overdue</span>':'on schedule'}</span><span class="muted">${esc(x.next_analysis_reason||'No pending reason')}</span></div>${x.analysis_history_complete?'': '<div class="warning">This chat has more than the maximum history loaded for the dashboard. Narrow the date range or use the analysis store for older records.</div>'}<details class="section" open><summary><span class="section-title">Decision transitions</span><span class="section-count">${esc((x.decision_groups||[]).length)} periods · ${esc(historyNote)}</span></summary>${renderTransitions(x)}</details><details class="section all-history"><summary><span class="section-title">Complete analysis log</span><span class="section-count">Every loaded analysis, newest first</span></summary><div class="analysis-log">${(x.analyses||[]).slice().reverse().map(renderAnalysisRow).join('')||'<div class="empty muted">No analysis has committed yet.</div>'}</div></details><details class="section"><summary><span class="section-title">Operational timeline</span><span class="section-count">queue · analyzer · policy · delivery</span></summary><div class="timeline">${(x.timeline||[]).map(renderEvent).join('')||'<span class="muted">No events yet</span>'}</div></details></article>`}
function renderTransitions(x){return `<div class="transitions">${(x.decision_groups||[]).slice().reverse().map(g=>`<details class="transition"><summary><span class="badge ${decisionClass(g.decision)}">${esc(g.decision)}</span><span class="transition-range">v${esc(g.start_version)}–v${esc(g.end_version)}</span><span class="transition-period">${shortFmt(g.start_at)} → ${shortFmt(g.end_at)}</span><span class="transition-count">${esc(g.analysis_count)} analyses</span></summary><div class="transition-body"><div class="transition-summary"><span>${chips(g.signals)}</span><span>${chips(g.categories)}</span><span>${esc(g.evidence_message_count)} relevant messages</span></div><div class="transition-reason"><b>Latest explanation:</b> ${esc(g.latest_reason||'—')}</div><h4>Relevant messages for this transition</h4><div class="transition-evidence">${renderMessages(g.evidence_messages||[])}</div></div></details>`).join('')||'<div class="empty muted">No transitions yet.</div>'}</div>`}
function renderMessages(messages){return messages.map(m=>`<div class="evidence"><b>${esc(m.direction)} · ${esc(m.sender||'unknown')} · ${fmt(m.timestamp)}</b><br>${esc(m.text)}</div>`).join('')||'<span class="muted">No evidence messages recorded.</span>'}
function renderEvidence(a,limit=0){const all=a.evidence_messages||[];const shown=limit?all.slice(-limit):all;const missing=(a.evidence_message_ids||[]).length-all.length;const header=limit&&all.length>limit?`<div class="muted">Showing the latest ${esc(limit)} of ${esc(all.length)} loaded messages.</div>`:'';const body=shown.map(m=>`<div class="evidence"><b>${esc(m.direction)} · ${esc(m.sender||'unknown')} · ${fmt(m.timestamp)}</b><br>${esc(m.text)}</div>`).join('');return `${header}${body||`<span class="muted">${missing>0?'Some evidence messages are unavailable.':'No evidence messages recorded.'}</span>`}`}
function renderAnalysisRow(a){const p=a.policy;const d=a.delivery;return `<details class="analysis-row" id="analysis-${esc(a.id)}"><summary><strong>v${esc(a.target_version)}</strong><span>${fmt(a.created_at)}</span><span class="badge ${decisionClass(a.decision)}">${esc(a.decision)}</span><span class="reason">${esc(a.reason)}</span><span>${esc((a.evidence_message_ids||[]).length)} evidence</span></summary><div class="analysis-detail"><div class="muted">${esc(a.model)} · prompt ${esc(a.prompt_version)} · analyzer ${esc(a.analyzer_version)} · taxonomy ${esc(a.taxonomy_version)}</div><div class="row"><b>Signals</b><div class="chips">${chips(a.signals)}</div><b>Categories</b><div class="chips">${chips(a.categories)}</div></div><div class="row"><b>Reason</b><div>${esc(a.reason)}</div></div><div class="two-col"><div class="box"><h4>Participants</h4>${participantText(a)}</div><div class="box"><h4>Policy and delivery</h4>${p?policyText(p):'No alert evaluation recorded'}${d?`<br>${deliveryText(d)}`:'<br>No alert created'}</div></div><details class="row"><summary>Evidence (${esc((a.evidence_message_ids||[]).length)})</summary>${renderEvidence(a)}</details></div></details>`}
function participantText(a){const roles=a.participant_diagnostics||[];const impact=a.participant_impact||[];return (roles.length?roles.map(p=>`<div>${esc(p.display_name||p.canonical_id||'unknown')} · ${esc(p.role||'unknown')}</div>`).join(''):'<div class="muted">No participant diagnostics</div>')+(impact.length?`<details><summary>Impact roles</summary><pre>${esc(JSON.stringify(impact,null,2))}</pre></details>`:'')}
function policyText(p){return p?`<span class="badge ${p.reason==='not_actionable'?'ok':p.reason==='policy_suppressed'?'concerning':''}">${esc(p.reason)}</span><div class="policy-detail">${esc(p.detail)}<br><span class="muted">${esc(p.outcome)} · ${fmt(p.evaluated_at)}</span></div>`:'No alert evaluation recorded'}
function deliveryText(d){return `<span class="badge ${d.action_status==='failed'||d.action_status==='indeterminate'?'fail':''}">${esc(d.action_status||d.alert_status)}</span> ${esc(d.reason)}${d.result_present?' · provider result recorded':''}`}
function renderEvent(e){return `<div class="event"><div class="event-title">${esc(e.title)} <span class="badge">${esc(e.status||'')}</span></div><div class="event-meta">${fmt(e.at)}${e.target_version?' · version '+e.target_version:''}</div><div class="event-detail">${esc(e.detail||'')}</div></div>`}
load();
</script></body></html>'''
